/* masterMpDsOrderInfoConfirmPop_div_pstmt4 */
INSERT INTO DB_OFF_IV ( BUYER, ADD_DATE, SEQ , DS_SEQ, STATUS, ADD_TIME, BYIT_COMORG_CODE, CONTRACT_NO, CONTRACT_SEQ, RD_DATE, BUYER_ITEM_NO, DS_QTY, ATOS_REMARK, ATOA_REMARK, BTOA_REMARK
) VALUES ( #{st_buyer}, --1 : BUYER #{st_add_date}, --2 : ADD_DATE ${st_seq}, SEQ_DB_OFF_IV.NEXTVAL, 'C', #{st_add_time}, --3 : ADD_TIME #{st_byit_comorg_code}, --2 : BYIT_COMORG_CODE #{st_contract_no}, --3 : CONTRACT_NO #{st_contract_seq}, --3 : CONTRACT_SEQ #{st_rd_date}, --4 : RD_DATE #{st_buyer_item_no}, --5 : BUYER_ITEM_NO ${st_ds_qty}, --6 : DS_QTY #{st_atos_remark}, --7 : ATOS_REMARK #{st_atoa_remark}, --8 : ATOA_REMARK #{st_btoa_remark} --9 : BTOA_REMARK )


